import { createHmac } from 'crypto'
import { cookies } from 'next/headers'

const SECRET = process.env.SESSION_SECRET!
export function sign(payload: string) { return createHmac('sha256', SECRET).update(payload).digest('base64url') }

export async function POST(req: Request) {
  const { userId } = await req.json()
  const body = JSON.stringify({ userId, iat: Date.now() })
  const token = `${Buffer.from(body).toString('base64url')}.${sign(body)}`
  cookies().set('eve_session', token, { httpOnly: true, sameSite: 'lax', secure: true, path: '/' })
  return Response.json({ ok: true })
}

import { cookies } from 'next/headers'
import { sign } from '@/app/api/auth/login/route'

export function verifySession() {
  const token = cookies().get('eve_session')?.value
  if (!token) return null
  const [body, mac] = token.split('.')
  const decoded = Buffer.from(body, 'base64url').toString()
  if (sign(decoded) !== mac) return null
  return JSON.parse(decoded) as { userId: string; iat: number }
}

import { verifySession } from '@/lib/auth/session'
import { loadScene, saveScene } from '@/lib/store/persistence'

export async function PUT(req: Request, { params }: { params: { id: string } }) {
  const session = verifySession()
  if (!session) return new Response('unauthorized', { status: 401 })
  const { elements, baseVersion } = await req.json()
  const stored = await loadScene(params.id)
  if (stored && baseVersion < stored.version) {
    return Response.json({ conflict: true, elements: stored.elements, version: stored.version }, { status: 409 })
  }
  const next = (stored?.version ?? 0) + 1
  await saveScene(params.id, { elements, version: next })
  return Response.json({ ok: true, version: next })
}

import { mergeScenes } from '@/lib/store/merge'

test('stale autosave returns 409 with the server scene', async () => {
  await saveScene('c1', { elements: [a], version: 5 })
  const res = await PUT(req({ elements: [b], baseVersion: 3 }), { params: { id: 'c1' } })
  expect(res.status).toBe(409)
  expect((await res.json()).version).toBe(5)
})

test('merge keeps distinct elements from both sides, server base wins on id clash', () => {
  const merged = mergeScenes({ elements: [a, x], version: 5 }, [b, { ...x, label: 'local' }])
  expect(merged.map((e) => e.id).sort()).toEqual(['a', 'b', 'x'])
  expect(merged.find((e) => e.id === 'x')!.label).toBe('server')
})
